def validate_records(records):
    issues = []
    for i, rec in enumerate(records):
        if not isinstance(rec.get("sku"), str) or not rec["sku"].strip():
            issues.append(f"row {i}: sku must be a non-empty string")
        for field in ("units", "price"):
            value = rec.get(field)
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                issues.append(f"row {i}: {field} must be numeric")
            elif value < 0:
                issues.append(f"row {i}: {field} must not be negative")
    return issues

def suspicious_features(records, target):
    if not records:
        return []
    suspects = []
    for key in records[0]:
        if key == target:
            continue
        if all(row.get(key) == row.get(target) for row in records):
            suspects.append(key)
    return sorted(suspects)

