from collections import Counter

def max_rate_change(reference, current):
    ref_total, cur_total = len(reference), len(current)
    categories = set(reference) | set(current)
    greatest = 0.0
    for category in categories:
        ref = Counter(reference).get(category, 0) / ref_total
        cur = Counter(current).get(category, 0) / cur_total
        greatest = max(greatest, abs(ref - cur))
    return round(greatest, 4)

