def _bits(chunk):
    table = {"r": 4, "w": 2, "x": 1}
    value = 0
    for ch in chunk:
        if ch == "-":
            continue
        if ch not in table:
            raise ValueError("invalid mode")
        value += table[ch]
    return value

def parse_mode(symbolic):
    if len(symbolic) != 9 or any(ch not in "rwx-" for ch in symbolic):
        raise ValueError("invalid mode")
    return _bits(symbolic[:3]) * 100 + _bits(symbolic[3:6]) * 10 + _bits(symbolic[6:9])

