import ipaddress

def is_allowed(rules, source_ip, port):
    ip = ipaddress.ip_address(source_ip)
    for rule in rules:
        try:
            network = ipaddress.ip_network(rule["cidr"])
        except ValueError:
            continue
        if ip in network and rule.get("port") == port:
            return True
    return False

def lint_dockerfile(lines):
    issues = []
    directives = [line.strip() for line in lines if line.strip() and not line.strip().startswith("#")]
    upper = [d.split()[0].upper() for d in directives]
    user_lines = [d for d in directives if d.split()[0].upper() == "USER"]
    if not user_lines:
        issues.append("user: no USER directive; the container runs as root by default")
    elif any(d.split()[1].lower() == "root" for d in user_lines if len(d.split()) > 1):
        issues.append("root: USER directive pins the container to uid 0")
    if "HEALTHCHECK" not in upper:
        issues.append("healthcheck: no HEALTHCHECK directive; orchestrators cannot detect a broken app")
    return issues

