def validate_manifest(manifest):
    issues = []
    spec = manifest.get("spec", {})
    if spec.get("replicas", 0) < 1:
        issues.append("replicas must be at least 1")
    containers = spec.get("template", {}).get("spec", {}).get("containers", [])
    if not containers:
        issues.append("at least one container is required")
        return issues
    container = containers[0]
    for probe in ("readinessProbe", "livenessProbe"):
        if not container.get(probe):
            issues.append(f"missing {probe}")
    resources = container.get("resources") or {}
    if not resources.get("requests") or not resources.get("limits"):
        issues.append("missing resources requests/limits")
    return issues

def parse_plan(output):
    marker = "Plan:"
    idx = output.find(marker)
    if idx == -1:
        return (0, 0, 0)
    segment = output[idx + len(marker):]
    end = segment.find(".")
    parts = segment[:end].split(",") if end != -1 else segment.split(",")
    counts = []
    for part in parts:
        tokens = part.split()
        number = int(tokens[0])
        counts.append(number)
    if any(count < 0 for count in counts):
        raise ValueError("invalid counts")
    return tuple(counts)

def decide(error_rate, p95_ms, max_error_rate, max_p95_ms):
    if error_rate > 2 * max_error_rate:
        return "rollback"
    if error_rate <= max_error_rate and p95_ms <= max_p95_ms:
        return "promote"
    return "hold"

