def overlaps(cidr_a, cidr_b):
    try:
        a = ipaddress.ip_network(cidr_a)
        b = ipaddress.ip_network(cidr_b)
    except ValueError:
        raise ValueError("invalid cidr")
    return a.overlaps(b)

